INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als Azubi meine Vergütung selbst verhandeln?', 2, '[{"text": "Nein", "correct": true, "because": "Tarif oder Gesetz legt fest"}, {"text": "Ja", "correct": false, "because": "Nur ohne Tarif möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ich als Azubi überhaupt Urlaub bekommen?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzlicher Anspruch"}, {"text": "Nein", "correct": false, "because": "Urlaub ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist meine Vergütung im ersten Lehrjahr höher als im zweiten?', 2, '[{"text": "Nein", "correct": true, "because": "Steigt mit Lehrjahr"}, {"text": "Ja", "correct": false, "because": "Logisch umgekehrt"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich im Urlaub weiter vergütet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Urlaubsentgelt gesetzlich"}, {"text": "Nein", "correct": false, "because": "Pflicht des Betriebs"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Muss ich Urlaub beantragen?', 2, '[{"text": "Ja", "correct": true, "because": "Abstimmung mit Betrieb nötig"}, {"text": "Nein", "correct": false, "because": "Kein Automatismus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Betrieb meine Vergütung kürzen, wenn ich krank bin?', 2, '[{"text": "Nein", "correct": true, "because": "Lohnfortzahlung gesetzlich"}, {"text": "Ja", "correct": false, "because": "Nur bei Missbrauch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist mein Urlaubsanspruch im Ausbildungsvertrag festgelegt?', 2, '[{"text": "Ja", "correct": true, "because": "Pflichtangabe"}, {"text": "Nein", "correct": false, "because": "Muss enthalten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich weniger als 20 Urlaubstage im Jahr haben?', 2, '[{"text": "Nein", "correct": true, "because": "Mindestanspruch für Jugendliche"}, {"text": "Ja", "correct": false, "because": "Gesetz schützt"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Wie viele Urlaubstage stehen mir als Azubi mindestens zu?', 2, '[{"text": "24", "correct": true, "because": "BUrlG Mindestanspruch"}, {"text": "10", "correct": false, "because": "Zu wenig"}, {"text": "40", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, ich bekomme keinen Urlaub im ersten Jahr. Was gilt?', 3, '[{"text": "Das ist illegal", "correct": true, "because": "Urlaub ist Pflicht"}, {"text": "Sie darf das", "correct": false, "because": "Gesetz widerspricht"}, {"text": "Nur im Probezeit", "correct": false, "because": "Auch da Anspruch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bestimmt meine Vergütung als Azubi?', 2, '[{"text": "Tarifvertrag", "correct": true, "because": "Häufigste Regelung"}, {"text": "Würfelwurf", "correct": false, "because": "Unsinn"}, {"text": "Laune des Chefs", "correct": false, "because": "Nicht rechtlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, ob ich im Dezember Urlaub nehmen kann. Was prüfe ich?', 3, '[{"text": "Betriebsferien", "correct": true, "because": "Könnte gesperrt sein"}, {"text": "Wetter", "correct": false, "because": "Irrelevant"}, {"text": "Mondphase", "correct": false, "because": "Kein Bezug"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was beeinflusst meine Vergütung als Azubi?', 4, '[{"text": "Tarifvertrag", "correct": true, "because": "Bindend bei Mitgliedschaft"}, {"text": "Lehrjahr", "correct": true, "because": "Steigt mit Zeit"}, {"text": "Branche", "correct": true, "because": "Unterschiede möglich"}, {"text": "Haarfarbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt für meinen Urlaub als Azubi?', 3, '[{"text": "Mindestens 24 Tage", "correct": true, "because": "Gesetzlicher Anspruch"}, {"text": "Antrag nötig", "correct": true, "because": "Abstimmung erforderlich"}, {"text": "Bezahlung im Urlaub", "correct": true, "because": "Entgelt läuft weiter"}, {"text": "Jederzeit möglich", "correct": false, "because": "Betrieb hat Mitsprache"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit über meinen Urlaub. Was kann ich tun?', 3, '[{"text": "Ausbilder ansprechen", "correct": true, "because": "Erste Instanz"}, {"text": "IHK informieren", "correct": true, "because": "Vermittlung möglich"}, {"text": "Anwalt einschalten", "correct": true, "because": "Rechtsschutz"}, {"text": "Streiken", "correct": false, "because": "Unverhältnismäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte habe ich bei der Vergütung?', 4, '[{"text": "Pünktliche Zahlung", "correct": true, "because": "Gesetzlich"}, {"text": "Lohnfortzahlung bei Krankheit", "correct": true, "because": "Arbeitsschutz"}, {"text": "Mindestvergütung", "correct": true, "because": "Reguliert"}, {"text": "Tägliche Auszahlung", "correct": false, "because": "Nicht üblich"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Urlaub steht mir auch in der Probezeit zu. b) Vergütung kann gekürzt werden, wenn ich fehle.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Urlaub ja, Kürzung nur bei Missbrauch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Meine Vergütung steigt mit dem Lehrjahr. b) Urlaub kann der Betrieb komplett verbieten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Steigung ja, Verbot illegal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ich habe Anspruch auf mindestens 24 Urlaubstage. b) Vergütung wird im Urlaub gestoppt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "24 Tage ja, Entgelt läuft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb muss meine Vergütung pünktlich zahlen. b) Ich kann Urlaub jederzeit nehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pünktlichkeit ja, Urlaub abgestimmt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

